12	// maxBufferedEvents caps a run's replayable event log. At ~1 bucket event per
13	// second this is over a day of run time — a backstop, not a working limit.
14	const maxBufferedEvents = 100_000
15	
16	// event is one serialized SSE frame: a 1-based sequence number (the SSE id,
17	// which browsers echo back as Last-Event-ID on reconnect), a type, and its
18	// marshaled JSON payload.
19	type event struct {
20		seq  int64
21		name string
22		data []byte
23	}
24	
25	// eventLog is a run's append-only event history plus live fanout. Every event
26	// is retained (bounded by maxBufferedEvents), so a subscriber at any point —
27	// first open, late join, browser reconnect — is handled the same way: replay
28	// everything after its Last-Event-ID, then stream. That makes dropping a slow
29	// subscriber lossless: it reconnects and replays what it missed.
30	type eventLog struct {
31		mu     sync.Mutex
32		events []event
33		subs   map[chan event]struct{}
34		closed bool
35	}
36	
37	func newEventLog() *eventLog {
38		return &eventLog{subs: make(map[chan event]struct{})}
39	}
40	
41	// emit marshals v, appends the event, and fans it out. A subscriber whose
42	// buffer is full is dropped (its channel closed) rather than blocking the
43	// coordinator; the SSE handler ends that response and the browser reconnects
44	// into a replay.
45	func (l *eventLog) emit(name string, v any) {
46		data, err := json.Marshal(v)
47		if err != nil {
48			// A marshal failure is a programming error in an event payload; surface
49			// it in-band rather than silently dropping the event.
50			data = fmt.Appendf(nil, `{"error":"marshal: %s"}`, err)
51		}
52		l.mu.Lock()
53		defer l.mu.Unlock()
54		// The cap bounds ONLY the bulk stream (one bucket event per second);
55		// lifecycle events always land. They are O(levels + targets) — a handful
56		// past the cap at most — and every consumer's correctness hangs on them:
57		// dropping a level_start/level_result would let the race podium crown a
58		// winner from an earlier level's data, and dropping run_done would leave
59		// every viewer of a capped run reconnect-looping forever. Bucket loss
60		// degrades gracefully (a gap in the replayed charts).
61		if l.closed || (len(l.events) >= maxBufferedEvents && name == "bucket") {
62			return
63		}
64		e := event{seq: int64(len(l.events)) + 1, name: name, data: data}
65		l.events = append(l.events, e)
66		for ch := range l.subs {
67			select {
68			case ch <- e:
69			default:
70				delete(l.subs, ch)
71				close(ch)
72			}
73		}
74	}
75	
76	// subscribe returns the replay of every event after seq `after`, plus a live
77	// channel (nil if the log is closed — the replay then already ends in the
78	// terminal event) and a cancel func.
79	func (l *eventLog) subscribe(after int64) ([]event, chan event, func()) {
80		l.mu.Lock()
81		defer l.mu.Unlock()
82		if after < 0 {
83			after = 0 // a malformed/negative Last-Event-ID must not index the slice negatively
84		}
85		var replay []event
86		if after < int64(len(l.events)) {
87			replay = append(replay, l.events[after:]...)
88		}
89		if l.closed {
90			return replay, nil, func() {}
91		}
92		ch := make(chan event, 256)
93		l.subs[ch] = struct{}{}
94		cancel := func() {
95			l.mu.Lock()
96			defer l.mu.Unlock()
97			if _, ok := l.subs[ch]; ok {
98				delete(l.subs, ch)
99				close(ch)
100			}
101		}
102		return replay, ch, cancel
103	}
104	
105	// close ends the log after the terminal event has been emitted: live
106	// subscribers are closed out (their replay already delivered everything) and
107	// future subscribers get replay-only.
108	func (l *eventLog) close() {
109		l.mu.Lock()
110		defer l.mu.Unlock()
111		l.closed = true
112		for ch := range l.subs {
113			delete(l.subs, ch)
114			close(ch)
115		}
116	}
