118	// serveSSE streams an eventLog as a Server-Sent-Events response: replay from
119	// the client's Last-Event-ID (or 0), then live events, with a comment
120	// heartbeat so proxies and the browser keep the connection alive.
121	func serveSSE(w http.ResponseWriter, r *http.Request, l *eventLog) {
122		fl, ok := w.(http.Flusher)
123		if !ok {
124			http.Error(w, "streaming unsupported", http.StatusInternalServerError)
125			return
126		}
127		var after int64
128		if v := r.Header.Get("Last-Event-ID"); v != "" {
129			after, _ = strconv.ParseInt(v, 10, 64)
130		}
131	
132		w.Header().Set("Content-Type", "text/event-stream")
133		w.Header().Set("Cache-Control", "no-cache")
134		w.Header().Set("X-Accel-Buffering", "no")
135		w.WriteHeader(http.StatusOK)
136	
137		replay, ch, cancel := l.subscribe(after)
138		defer cancel()
139		for _, e := range replay {
140			writeSSE(w, e)
141		}
142		fl.Flush()
143		if ch == nil {
144			return // run already finished; the replay ended in run_done
145		}
146	
147		heartbeat := time.NewTicker(15 * time.Second)
148		defer heartbeat.Stop()
149		for {
150			select {
151			case e, ok := <-ch:
152				if !ok {
153					return // log closed (run finished) or we were dropped as slow
154				}
155				writeSSE(w, e)
156				fl.Flush()
157			case <-heartbeat.C:
158				_, _ = fmt.Fprint(w, ": ping\n\n")
159				fl.Flush()
160			case <-r.Context().Done():
161				return
162			}
163		}
164	}
165	
166	func writeSSE(w http.ResponseWriter, e event) {
167		_, _ = fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", e.seq, e.name, e.data)
168	}
