192	// sampleLatency draws one op's synthetic latency, clamped into [1ms, 1h]
193	// BEFORE the float→Duration conversion. The clamp is a hard safety bound, not
194	// shaping: with an extreme-but-finite spread (say 1e308, which parses fine)
195	// the product overflows float64 or int64, and Go's float→int conversion on
196	// overflow is implementation-defined — a zero/negative duration would make
197	// time.After fire instantly and turn every agent into an unbounded
198	// sample-allocating spin. The floor also bounds the op rate (≤1000/s per
199	// agent) for legitimately tiny p50s; real git ops are never sub-millisecond.
200	func (d *demoRunner) sampleLatency(rng *rand.Rand, inflate float64) time.Duration {
201		f := float64(d.p50) * inflate * math.Exp(d.sigma*rng.NormFloat64())
202		return time.Duration(math.Min(math.Max(f, float64(time.Millisecond)), float64(time.Hour)))
203	}
