205	func (d *demoRunner) RunLevel(ctx context.Context, c int, barrier *bench.StartBarrier) (bench.LevelResult, error) {
206		// Saturation: offered load approaches cap → queueing inflates latency.
207		inflate := 1.0
208		if d.cap > 0 {
209			offered := float64(c) / d.p50.Seconds()
210			util := math.Min(offered/d.cap, 0.95)
211			inflate = 1 / (1 - util)
212		}
213	
214		// Wait for the shared start so the demo target's window aligns with the
215		// real targets it's compared against.
216		if barrier != nil {
217			barrier.Arrive()
218			barrier.Hold()
219		}
220	
221		// Origin both the deadline and the sample clock on the barrier's shared fire
222		// instant, exactly like bench.Runner, so scheduler delay after release can't
223		// shift or extend the demo's window past the real targets it races against
224		// (which would give it extra ops and make live buckets disagree with the
225		// final result).
226		total := d.w.Warmup + d.w.Duration
227		start := time.Now()
228		if barrier != nil {
229			start = barrier.FiredAt()
230		}
231		lctx, cancel := context.WithDeadline(ctx, start.Add(total))
232		defer cancel()
233		agg := &demoAgg{warmup: d.w.Warmup}
234		var wg sync.WaitGroup
235		for i := range c {
236			wg.Add(1)
237			go func(id int) {
238				defer wg.Done()
239				// Deterministic per agent, like the engine's commit content rng.
240				rng := rand.New(rand.NewSource(int64(id)*7919 + 42)) //nolint:gosec // synthetic demo data
241				pushesLeft := 0                                      // session state: pushes remaining before the next clone
242				for lctx.Err() == nil {
243					lat := d.sampleLatency(rng, inflate)
244					t0 := time.Now()
245					select {
246					case <-time.After(lat):
247					case <-lctx.Done():
248						return // drop the truncated op, like the engine does
249					}
