16	// demoRunner synthesizes push samples so the whole pipeline — level barriers,
17	// collector, SSE, charts, persistence — can be exercised and demoed with no
18	// forge and no network. It is selected by a demo:// remote:
19	//
20	//	demo://fast?p50=80ms&spread=3&err=0.01&cas=0.02&cap=200
21	//
22	//	p50     median latency (Go duration; default 80ms)
23	//	spread  p99/p50 shape multiplier of the log-normal tail (default 3)
24	//	err     probability an op fails (default 0.01)
25	//	cas     probability an op is a CAS rejection (default 0)
26	//	cap     ops/sec saturation ceiling; approaching it inflates latency the
27	//	        way a real forge queues (default 0 = unbounded)
28	//
29	// Each concurrency level runs c goroutines that sleep a sampled latency per
30	// op, so throughput scales with concurrency until cap bends the curve — the
31	// same shapes a real sweep produces.
32	type demoRunner struct {
33		label   string
34		w       bench.Workload
35		sink    bench.Sink
36		p50     time.Duration
37		sigma   float64 // log-normal shape derived from spread
38		errRate float64
39		casRate float64
40		cap     float64
41	}
