48	func newDemoRunner(remote string, w bench.Workload, sink bench.Sink) (*demoRunner, error) {
49		u, err := url.Parse(remote)
50		if err != nil || u.Scheme != "demo" {
51			return nil, fmt.Errorf("invalid demo remote %q", remote)
52		}
53		q := u.Query()
54		d := &demoRunner{label: remote, w: w, sink: sink, p50: 80 * time.Millisecond, errRate: 0.01}
55		spread := 3.0
56		if v := q.Get("p50"); v != "" {
57			if d.p50, err = time.ParseDuration(v); err != nil || d.p50 <= 0 {
58				return nil, fmt.Errorf("demo: invalid p50 %q", v)
59			}
60		}
61		for name, dst := range map[string]*float64{"spread": &spread, "err": &d.errRate, "cas": &d.casRate, "cap": &d.cap} {
62			if v := q.Get(name); v != "" {
63				f, err := strconv.ParseFloat(v, 64)
64				// Reject NaN/±Inf explicitly: ParseFloat accepts them, and they pass a
65				// bare `f < 0` check, then poison sigma/durations and can spin a tight
66				// synthetic loop.
67				if err != nil || math.IsNaN(f) || math.IsInf(f, 0) || f < 0 {
68					return nil, fmt.Errorf("demo: invalid %s %q", name, v)
69				}
70				*dst = f
71			}
72		}
73		if spread < 1 {
74			return nil, fmt.Errorf("demo: spread must be >= 1")
75		}
76		// err and cas are probabilities per operation.
77		if d.errRate > 1 || d.casRate > 1 {
78			return nil, fmt.Errorf("demo: err and cas must be probabilities in [0,1]")
79		}
80		// Both outcomes resolve from one shared roll (bands [0,err) and
81		// [err,err+cas)), so a sum over 1 would silently clip the CAS band — e.g.
82		// err=0.8&cas=0.8 would yield only ~0.2 CAS instead of the requested 0.8.
83		if d.errRate+d.casRate > 1 {
84			return nil, fmt.Errorf("demo: err + cas must not exceed 1 (each op resolves one shared probability roll)")
85		}
86		// For a log-normal around the median, p99 = median * exp(sigma * z99).
87		d.sigma = math.Log(spread) / 2.326
88		return d, nil
89	}
