95	// nextOp mirrors the real strategies' op mix so demo buckets exercise the
96	// same consumer paths: clone strategy emits only clones; session emits one
97	// clone and then, ONLY if that clone succeeded, SessionCommits pushes before
98	// the next clone — a real session agent retries the clone immediately after
99	// a clone failure (runSessions' `continue`), so an error-heavy demo must not
100	// publish pushes against a session that never cloned. pushesLeft is the
101	// agent's session state: how many pushes remain in its current session.
102	func (d *demoRunner) nextOp(pushesLeft int) bench.OpKind {
103		switch d.w.Strategy {
104		case "clone":
105			return bench.OpClone
106		case "session":
107			if pushesLeft == 0 {
108				return bench.OpClone
109			}
110		}
111		return bench.OpPush
112	}
