// and one permanently pinned ref is a constant, not the unbounded growth
// this sweep exists to bound.
func sweepSpecs(refs []*plumbing.Reference, re *regexp.Regexp, cutoff time.Time) []config.RefSpec {
	headTarget, headHash := "", plumbing.ZeroHash
