// alone (whether HEAD arrives as a symref or as a bare tip hash) instead of
// failing on every subsequent run, while still deleting the other stale refs.
func TestSweepSpecsSpareDefaultBranch(t *testing.T) {
	re := staleBenchRefRe("bench/")
	cutoff := time.Now() // everything below is "old enough"
	oldID := "fm" + strconv.FormatInt(time.Now().Add(-3*staleAfter).UnixNano(), 36)
	pinned := plumbing.ReferenceName("refs/heads/bench/" + oldID + "-c1-a0")
	other := plumbing.ReferenceName("refs/heads/bench/" + oldID + "-c1-a1")
	tip := plumbing.NewHash("0102030405060708090a0b0c0d0e0f1011121314")
	otherTip := plumbing.NewHash("a1a2a3a4a5a6a7a8a9aaabacadaeafb0b1b2b3b4")

	names := func(specs []config.RefSpec) []string {
		out := make([]string, len(specs))
		for i, s := range specs {
			out[i] = strings.TrimPrefix(string(s), ":")
		}
		return out
	}

	// HEAD advertised as a symref (smart HTTP with symref capability).
	specs := sweepSpecs([]*plumbing.Reference{
		plumbing.NewSymbolicReference(plumbing.HEAD, pinned),
		plumbing.NewHashReference(pinned, tip),
		plumbing.NewHashReference(other, otherTip),
	}, re, cutoff)
	if got := names(specs); !slices.Equal(got, []string{other.String()}) {
		t.Errorf("symref HEAD: sweep would delete %v, want only %v", got, other)
	}

	// HEAD advertised as a bare hash ref (no symref in the advertisement).
	specs = sweepSpecs([]*plumbing.Reference{
		plumbing.NewHashReference(plumbing.HEAD, tip),
		plumbing.NewHashReference(pinned, tip),
		plumbing.NewHashReference(other, otherTip),
	}, re, cutoff)
	if got := names(specs); !slices.Equal(got, []string{other.String()}) {
		t.Errorf("hash HEAD: sweep would delete %v, want only %v", got, other)
	}

	// No HEAD at all (unborn HEAD but refs exist): everything stale goes.
	specs = sweepSpecs([]*plumbing.Reference{
		plumbing.NewHashReference(pinned, tip),
		plumbing.NewHashReference(other, otherTip),
	}, re, cutoff)
	if got := names(specs); len(got) != 2 {
		t.Errorf("no HEAD: sweep selected %v, want both stale refs", got)
	}
}

